// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/BroadcastScene.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Broadcast, rebuilt from the app's BroadcastBar (src/grid/BroadcastBar.tsx):
 * selected tiles get the accent outline and their sessions become chips in a
 * composer docked at the bottom of the canvas. While the scene is on screen
 * it plays the feature: a message is typed into the composer, sent, and lands
 * in every selected terminal at once: real Claude Code captures of it.
 * Any click or keystroke in the scene stops the loop and hands it over:
 * clicking a header adds or removes a tile (shift-click in the app), and Send
 * delivers what was typed.
 */
import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { Bot, MessageSquareText, Mic, Radio, SendHorizontal, SquareTerminal, X } from "lucide-react";
import { AgentMark, Term, Tile, type Agent } from "./AppUI";
import { AnsiScreen } from "./ansi";
import type { CaptureId } from "./captures";
import { THIS_MAC } from "./Chrome";

interface SceneTile {
  id: string;
  name: string;
  agent: Agent;
  /** The session as captured at this tile's size (65 columns). */
  capture: CaptureId;
  /** The same session moments after the broadcast message reached it. */
  arrival?: CaptureId;
}

const TILES: SceneTile[] = [
  { id: "api", name: "api", agent: "claude", capture: "api-65", arrival: "api-65-arrival" },
  { id: "web", name: "web", agent: "claude", capture: "web-65", arrival: "web-65-arrival" },
  { id: "docs", name: "docs", agent: "claude", capture: "docs-65", arrival: "docs-65-arrival" },
  { id: "release", name: "release", agent: "claude", capture: "release-65" },
];

const MESSAGE = "Run the tests and fix what fails";

// How long the dock takes to slide away (the app's broadcast-dock-out).
const LEAVE_MS = 200;
// The loop: type the message, pause, send, let it land, start over.
const TYPE_MS = 26;
const BEFORE_SEND_MS = 650;
const PRESS_MS = 160;
const AFTER_SEND_MS = 4200;

const wait = (ms: number) => new Promise<void>((resolve) => window.setTimeout(resolve, ms));

export function BroadcastScene({ children }: { children?: ReactNode }) {
  const [selected, setSelected] = useState<string[]>(["api", "web", "docs"]);
  const [text, setText] = useState(MESSAGE);
  const [status, setStatus] = useState<string | null>(null);
  const [delivered, setDelivered] = useState<{ to: string[]; message: string } | null>(null);
  const [pressing, setPressing] = useState(false);
  const [shown, setShown] = useState(true);
  const [handedOver, setHandedOver] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const footId = useId();
  const canvas = useRef<HTMLElement>(null);
  const grid = useRef<HTMLDivElement>(null);
  const bar = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<{ left: number; width: number; bottom: number } | null>(null);
  const [covering, setCovering] = useState(false);
  const active = selected.length >= 2;
  const tiles = TILES.filter((tile) => selected.includes(tile.id));
  const missingAgents = TILES.filter((tile) => tile.agent !== "terminal" && !selected.includes(tile.id)).length;

  // Becoming active shows the composer again in the same render (not a second pass from an effect).
  if (active && !shown) setShown(true);

  // The composer stays on screen while it slides away, then unmounts.
  useEffect(() => {
    if (active) return;
    const timer = window.setTimeout(() => setShown(false), LEAVE_MS);
    return () => window.clearTimeout(timer);
  }, [active]);

  // Play the feature while the scene is on screen, until someone takes over.
  useEffect(() => {
    const element = root.current;
    if (!element || handedOver || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let visible = false;
    let cancelled = false;
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
    }, { threshold: 0.5 });
    observer.observe(element);
    const play = async () => {
      while (!cancelled) {
        if (!visible) {
          await wait(300);
          continue;
        }
        setDelivered(null);
        setStatus(null);
        for (let i = 0; i <= MESSAGE.length && !cancelled; i += 1) {
          setText(MESSAGE.slice(0, i));
          await wait(TYPE_MS);
        }
        await wait(BEFORE_SEND_MS);
        if (cancelled) return;
        setPressing(true);
        await wait(PRESS_MS);
        if (cancelled) return;
        setPressing(false);
        setDelivered({ to: ["api", "web", "docs"], message: MESSAGE });
        setStatus("Sent to 3 sessions.");
        setText("");
        await wait(AFTER_SEND_MS);
      }
    };
    void play();
    return () => {
      cancelled = true;
      observer.disconnect();
      setPressing(false);
    };
  }, [handedOver]);

  // A terminal shows its latest output: new lines push the view to the bottom.
  useLayoutEffect(() => {
    root.current?.querySelectorAll<HTMLElement>(".pz-term").forEach((term) => {
      term.scrollTop = term.scrollHeight;
    });
  }, [delivered]);

  // The dock is fixed over the canvas's box (here the window is its
  // containing block, as the app's viewport is), and the spacer under the
  // grid takes the composer's height (--broadcast-h), measured like
  // BroadcastBar does. The fade reaches up over the tiles only while they
  // run under the composer.
  useLayoutEffect(() => {
    const host = canvas.current;
    const element = bar.current;
    const win = host?.closest<HTMLElement>(".pz-window");
    if (!shown || !host || !element || !win) return;
    const measure = () => {
      host.style.setProperty("--broadcast-h", `${Math.ceil(element.offsetHeight)}px`);
      const outer = win.getBoundingClientRect();
      const rect = host.getBoundingClientRect();
      // The scene is scaled to its card; the box is in the window's own pixels.
      const scale = outer.width / win.offsetWidth || 1;
      const next = { left: Math.round((rect.left - outer.left) / scale), width: host.clientWidth, bottom: Math.round((outer.bottom - rect.bottom) / scale) };
      setBox((previous) => (previous && previous.left === next.left && previous.width === next.width && previous.bottom === next.bottom ? previous : next));
      setCovering(!!grid.current && grid.current.getBoundingClientRect().bottom > element.getBoundingClientRect().top + 1);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    observer.observe(host);
    if (grid.current) observer.observe(grid.current);
    return () => {
      observer.disconnect();
      host.style.removeProperty("--broadcast-h");
    };
  }, [shown]);

  const takeOver = () => {
    if (!handedOver) setHandedOver(true);
  };
  const toggle = (id: string) => {
    setStatus(null);
    setSelected((value) => (value.includes(id) ? value.filter((item) => item !== id) : [...value, id]));
  };
  const send = () => {
    if (!text.trim()) return;
    setDelivered({ to: selected, message: text.trim() });
    setStatus(`Sent to ${tiles.length} sessions.`);
    setText("");
  };
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      send();
    } else if (event.key === "Escape") {
      event.preventDefault();
      setSelected([]);
    }
  };

  return (
    <div className="pz-bc" ref={root} onPointerDown={takeOver} onKeyDown={takeOver}>
      {children}
      {/* The app's canvas (src/grid/Canvas.tsx): the grid, then the dock's spacer and the dock. */}
      <div className="body">
        <main ref={canvas} className="canvas">
          <div
            ref={grid}
            className={`grid ${shown ? "grid-with-broadcast" : ""}`}
            style={{ gridTemplateColumns: "1fr 1fr" }}
            onClick={(event) => {
              // A press on a tile's header (shift-click in the app) adds or removes it.
              if (!(event.target instanceof Element) || !event.target.closest(".tile-head") || event.target.closest(".tile-btn")) return;
              const tile = event.target.closest(".tile");
              const index = tile ? Array.prototype.indexOf.call(event.currentTarget.children, tile) : -1;
              if (index >= 0) toggle(TILES[index].id);
            }}
          >
            {TILES.map((tile, i) => {
              // The captured arrival shows this exact message; any other message leaves the screen as it was.
              const arrived = delivered?.to.includes(tile.id) && delivered.message === MESSAGE ? tile.arrival : undefined;
              return (
                <Tile
                  key={tile.id}
                  title={tile.name}
                  agent={tile.agent}
                  kbd={`⌘${i + 1}`}
                  device={THIS_MAC}
                  selected={selected.includes(tile.id)}
                  inactive={!selected.includes(tile.id)}
                  headTitle="Click to add to or remove from the broadcast"
                >
                  <Term>
                    <AnsiScreen id={arrived ?? tile.capture} />
                  </Term>
                </Tile>
              );
            })}
          </div>
          {shown ? <div className="broadcast-spacer" aria-hidden="true" /> : null}
          {shown ? (
            <div
              className={`broadcast-dock${covering ? " broadcast-dock-covering" : ""}${active ? "" : " broadcast-dock-leaving"}${box ? "" : " broadcast-dock-measuring"}`}
              style={box ?? undefined}
            >
              {/* Blur that deepens toward the bottom edge, so whatever scrolls under the
                  composer fades out behind it instead of running into its edge. */}
              <div className="broadcast-fade" aria-hidden="true">
                <span />
                <span />
                <span />
                <span />
              </div>
              <div ref={bar} className="broadcast-bar" role="region" aria-label="Broadcast to selected sessions">
                <div className="broadcast-head">
                  <span className="broadcast-title">
                    <Radio size={14} className="broadcast-icon" aria-hidden="true" />
                    Broadcast
                  </span>
                  <ul className="broadcast-targets" aria-label="Selected sessions">
                    {tiles.map((tile) => (
                      <li key={tile.id} className="broadcast-chip" title={tile.name}>
                        {tile.agent === "terminal" ? <SquareTerminal size={12} aria-hidden="true" /> : <AgentMark agent={tile.agent} size={12} />}
                        <span className="broadcast-chip-name">{tile.name}</span>
                        <button
                          type="button"
                          className="broadcast-chip-remove"
                          aria-label={`Remove ${tile.name}`}
                          title="Remove from the broadcast"
                          onClick={() => toggle(tile.id)}
                        >
                          <X size={11} />
                        </button>
                      </li>
                    ))}
                  </ul>
                  {missingAgents ? (
                    <button
                      type="button"
                      className="tile-btn broadcast-agents"
                      title="Add every tile running a coding agent in this workspace"
                      onClick={() => setSelected(TILES.filter((tile) => tile.agent !== "terminal" || selected.includes(tile.id)).map((tile) => tile.id))}
                    >
                      <Bot size={14} aria-hidden="true" />
                      All agents<span className="broadcast-agents-count">+{missingAgents}</span>
                    </button>
                  ) : null}
                  <button type="button" className="tile-btn broadcast-close" title="Clear selection (Esc)" aria-label="Clear selection" onClick={() => setSelected([])}>
                    <X size={14} />
                  </button>
                </div>
                <div className="broadcast-compose">
                  {/* PromptPicker: the saved prompts menu, closed. */}
                  <div className="broadcast-prompts">
                    <button type="button" className="tile-btn" title="Saved prompts" aria-label="Saved prompts" aria-haspopup="menu" aria-expanded={false}>
                      <MessageSquareText size={14} aria-hidden="true" />
                    </button>
                  </div>
                  <div className="broadcast-field">
                    <textarea
                      className="broadcast-input"
                      value={text}
                      rows={1}
                      placeholder={`Type a message to send to ${tiles.length === 2 ? "both" : `all ${tiles.length}`} sessions…`}
                      aria-label={`Send to ${tiles.length} sessions`}
                      aria-describedby={footId}
                      spellCheck={false}
                      maxLength={4096}
                      onChange={(event) => {
                        setText(event.target.value);
                        setStatus(null);
                      }}
                      onKeyDown={onKeyDown}
                    />
                  </div>
                  {/* DictationButton, with dictation set up on this Mac. */}
                  <button type="button" className="tile-btn " title="Start dictation" aria-label="Start dictation" aria-busy={false}>
                    <Mic size={13} />
                  </button>
                  <button
                    type="button"
                    className={`tile-btn broadcast-send${pressing ? " is-pressed" : ""}`}
                    aria-label="Send"
                    title="Send (Enter). Shift+Enter adds a line. Sessions waiting on an approval prompt are skipped."
                    disabled={!text.trim()}
                    onClick={send}
                  >
                    <SendHorizontal size={15} aria-hidden="true" />
                  </button>
                </div>
                <div id={footId} className={`broadcast-foot ${status ? "broadcast-status" : ""} `} role="status">
                  {status}
                </div>
              </div>
            </div>
          ) : null}
        </main>
      </div>
    </div>
  );
}
